import React, { useState, useEffect, useRef } from 'react';
import { toast } from 'react-toastify';
import { FiPlus, FiEdit2, FiTrash2, FiStar } from 'react-icons/fi';
import api from '../../services/api';
import { getImageUrl } from '../../utils/helpers';
import AdminTable from '../common/AdminTable';
import AdminModal from '../common/AdminModal';
import AdminCard from '../common/AdminCard';

const DEFAULT_AVATAR = '/default-avatar.png';

const AdminTestimonials = () => {
  const [testimonials, setTestimonials] = useState([]);
  const [loading, setLoading] = useState(true);
  const [modalOpen, setModalOpen] = useState(false);
  const [editingTestimonial, setEditingTestimonial] = useState(null);
  const [formData, setFormData] = useState({
    name: '',
    role: '',
    content: '',
    rating: 5,
    is_active: true,
    order: 0,
  });
  const [avatarFile, setAvatarFile] = useState(null);
  const [avatarPreview, setAvatarPreview] = useState(null);
  const fileInputRef = useRef(null);

  useEffect(() => {
    fetchTestimonials();
  }, []);

  const fetchTestimonials = async () => {
    try {
      const response = await api.get('/api/testimonials/');
      setTestimonials(response.data);
    } catch (error) {
      toast.error('Failed to load testimonials');
    } finally {
      setLoading(false);
    }
  };

  const resetForm = () => {
    setFormData({
      name: '',
      role: '',
      content: '',
      rating: 5,
      is_active: true,
      order: 0,
    });
    setAvatarFile(null);
    if (avatarPreview) {
      URL.revokeObjectURL(avatarPreview);
    }
    setAvatarPreview(null);
    setEditingTestimonial(null);
  };

  const handleAvatarChange = (e) => {
    const file = e.target.files[0];
    if (!file) return;

    // Revoke previous preview URL if any
    if (avatarPreview) {
      URL.revokeObjectURL(avatarPreview);
    }

    setAvatarFile(file);
    setAvatarPreview(URL.createObjectURL(file));
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    try {
      const data = new FormData();
      data.append('name', formData.name);
      data.append('role', formData.role);
      data.append('content', formData.content);
      data.append('rating', String(formData.rating));
      data.append('is_active', String(formData.is_active));
      data.append('order', String(formData.order));

      if (avatarFile) {
        data.append('avatar', avatarFile);
      }

      if (editingTestimonial) {
        await api.put(`/api/testimonials/${editingTestimonial.id}`, data, {
          headers: { 'Content-Type': 'multipart/form-data' },
        });
        toast.success('Testimonial updated successfully');
      } else {
        await api.post('/api/testimonials/', data, {
          headers: { 'Content-Type': 'multipart/form-data' },
        });
        toast.success('Testimonial created successfully');
      }

      setModalOpen(false);
      resetForm();
      fetchTestimonials();
    } catch (error) {
      console.error(error);
      const detail =
        error.response?.data?.detail ||
        error.response?.data?.message ||
        'Operation failed';
      toast.error(detail);
    }
  };

  const handleDelete = async (id) => {
    if (window.confirm('Are you sure you want to delete this testimonial?')) {
      try {
        await api.delete(`/api/testimonials/${id}`);
        toast.success('Testimonial deleted successfully');
        fetchTestimonials();
      } catch (error) {
        console.error(error);
        toast.error('Failed to delete testimonial');
      }
    }
  };

  const handleEdit = (testimonial) => {
    setEditingTestimonial(testimonial);
    setFormData({
      name: testimonial.name,
      role: testimonial.role || '',
      content: testimonial.content,
      rating: testimonial.rating,
      is_active: testimonial.is_active,
      order: testimonial.order,
    });
    setAvatarFile(null);
    if (avatarPreview) {
      URL.revokeObjectURL(avatarPreview);
    }
    setAvatarPreview(null);
    setModalOpen(true);
  };

  const openCreateModal = () => {
    resetForm();
    if (fileInputRef.current) {
      fileInputRef.current.value = '';
    }
    setModalOpen(true);
  };

  const closeModal = () => {
    setModalOpen(false);
    resetForm();
  };

  const renderStars = (rating) => {
    return (
      <div className="flex">
        {[...Array(5)].map((_, i) => (
          <FiStar
            key={i}
            className={`${i < rating ? 'text-yellow-400 fill-current' : 'text-gray-300'}`}
            size={16}
          />
        ))}
      </div>
    );
  };

  const columns = [
    {
      key: 'avatar',
      label: 'Avatar',
      render: (val) => (
        <img
          src={getImageUrl(val, DEFAULT_AVATAR)}
          alt="avatar"
          className="w-12 h-12 rounded-full object-cover"
          onError={(e) => { e.target.src = DEFAULT_AVATAR; }}
        />
      ),
    },
    { key: 'name', label: 'Name' },
    { key: 'role', label: 'Role' },
    {
      key: 'content',
      label: 'Content',
      render: (val) => (
        <span className="text-sm text-gray-600 line-clamp-2 max-w-xs">{val}</span>
      ),
    },
    {
      key: 'rating',
      label: 'Rating',
      render: (val) => renderStars(val),
    },
    {
      key: 'is_active',
      label: 'Status',
      render: (val) => (
        <span className={`px-2 py-1 rounded-full text-xs ${
          val ? 'bg-green-100 text-green-800' : 'bg-red-100 text-red-800'
        }`}>
          {val ? 'Active' : 'Inactive'}
        </span>
      ),
    },
    {
      key: 'actions',
      label: 'Actions',
      render: (_, row) => (
        <div className="flex space-x-2">
          <button
            onClick={() => handleEdit(row)}
            className="text-blue-600 hover:text-blue-800"
          >
            <FiEdit2 />
          </button>
          <button
            onClick={() => handleDelete(row.id)}
            className="text-red-600 hover:text-red-800"
          >
            <FiTrash2 />
          </button>
        </div>
      ),
    },
  ];

  return (
    <div>
      <div className="flex justify-between items-center mb-6">
        <h1 className="text-3xl font-bold text-blue-900">Testimonials Management</h1>
        <button
          onClick={openCreateModal}
          className="admin-btn-primary flex items-center space-x-2"
        >
          <FiPlus />
          <span>Add Testimonial</span>
        </button>
      </div>

      <AdminCard>
        <AdminTable
          columns={columns}
          data={testimonials}
          loading={loading}
        />
      </AdminCard>

      <AdminModal
        isOpen={modalOpen}
        onClose={closeModal}
        title={editingTestimonial ? 'Edit Testimonial' : 'Create Testimonial'}
      >
        <form onSubmit={handleSubmit}>
          <div className="space-y-4">
            <div>
              <label className="admin-label">Name *</label>
              <input
                type="text"
                value={formData.name}
                onChange={(e) => setFormData({ ...formData, name: e.target.value })}
                className="admin-input"
                required
              />
            </div>
            <div>
              <label className="admin-label">Role (e.g. Student, English Program)</label>
              <input
                type="text"
                value={formData.role}
                onChange={(e) => setFormData({ ...formData, role: e.target.value })}
                className="admin-input"
                placeholder="Student, English Program"
              />
            </div>
            <div>
              <label className="admin-label">Content *</label>
              <textarea
                value={formData.content}
                onChange={(e) => setFormData({ ...formData, content: e.target.value })}
                className="admin-input"
                rows="4"
                required
              />
            </div>
            <div>
              <label className="admin-label">Avatar Image</label>
              <input
                ref={fileInputRef}
                type="file"
                accept="image/jpeg,image/png,image/webp"
                onChange={handleAvatarChange}
                className="admin-input"
              />
              {/* Preview: show either newly selected image or existing avatar */}
              {(avatarPreview || (editingTestimonial && editingTestimonial.avatar)) && (
                <div className="mt-3 flex justify-center">
                  <img
                    src={avatarPreview || getImageUrl(editingTestimonial.avatar, DEFAULT_AVATAR)}
                    alt="Avatar preview"
                    className="w-24 h-24 rounded-full object-cover border-2 border-gray-200"
                    onError={(e) => { e.target.src = DEFAULT_AVATAR; }}
                  />
                </div>
              )}
            </div>
            <div>
              <label className="admin-label">Rating (1-5)</label>
              <input
                type="number"
                min="1"
                max="5"
                value={formData.rating}
                onChange={(e) => setFormData({ ...formData, rating: parseInt(e.target.value) || 5 })}
                className="admin-input"
              />
            </div>
            <div>
              <label className="admin-label">Order</label>
              <input
                type="number"
                min="0"
                value={formData.order}
                onChange={(e) => setFormData({ ...formData, order: parseInt(e.target.value) || 0 })}
                className="admin-input"
              />
            </div>
            <div>
              <label className="flex items-center space-x-2">
                <input
                  type="checkbox"
                  checked={formData.is_active}
                  onChange={(e) => setFormData({ ...formData, is_active: e.target.checked })}
                />
                <span>Active</span>
              </label>
            </div>
          </div>
          <div className="mt-6 flex justify-end space-x-3">
            <button
              type="button"
              onClick={closeModal}
              className="admin-btn-secondary"
            >
              Cancel
            </button>
            <button type="submit" className="admin-btn-primary">
              {editingTestimonial ? 'Update' : 'Create'}
            </button>
          </div>
        </form>
      </AdminModal>
    </div>
  );
};

export default AdminTestimonials;
